// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] calldata tos, uint[] calldata vs) public {
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        // We need a contract that will accept the call without reverting.
        // We deploy a simple mock that always returns true for transferFrom.
        MockReceiver mock = new MockReceiver();
        contract_address = address(mock);
        bool returned = c.transfer(contract_address, tos, vs);
        assertTrue(returned);
    }
}

contract MockReceiver {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory tos, uint[] memory vs) public payable {
        require(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        bool reverted; try c.transfer(address(this), tos, vs) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        require(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        bool reverted;
        try c.transfer(contract_address, tos, vs) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
}
